for f,pairs in J.items():
    s=open(R+f).read()
    m=re.search(r'const REJA = \[(.*?)\n\];',s,re.S); blk=m.group(1); nb=blk
    for a,b in pairs:
        assert nb.count(a)==1,(f,a); nb=nb.replace(a,b)
    s=s[:m.start(1)]+nb+s[m.end(1):]; open(R+f,'w').write(s)
    print('ok',f,len(pairs))
# yakuniy MD lar: o'sha qatorlar
alls=[p for v in J.values() for p in v]
n=0
for md in glob.glob(R+'feedback/F-1018-pitch/YAKUNIY-*.md'):
    t=open(md).read(); t0=t
    for a,b in alls: t=t.replace(a,b)
    if t!=t0: open(md,'w').write(t); n+=1
print('MD yangilandi:',n)
